-- Testimonialele: doar dacă tabelul e gol (nu suprascriem editările ulterioare).
insert into public.fw_testimonials (name, role_ro, role_en, quote_ro, quote_en, sort_order)
select * from (values
  ($q$Cătălina G.$q$, $q$Manager IT$q$, $q$IT Manager$q$, $q$Colaborarea cu echipa Full Work Services a fost una dintre cele mai echilibrate experiențe din zona de recrutare. Procesul a fost transparent, comunicarea excelentă, iar selecția finală a reflectat perfect valorile și nevoile companiei noastre.$q$, $q$Working with the Full Work Services team was one of the most balanced recruitment experiences. The process was transparent, the communication was excellent, and the final selection perfectly reflected our company's values and needs.$q$, 1),
  ($q$Ioana G.$q$, $q$Manager fabrică$q$, $q$Factory Manager$q$, $q$Am apreciat enorm corectitudinea și atenția la detalii. Fiecare candidat a fost evaluat nu doar după competențe, ci și după compatibilitatea cu echipa. Rareori am întâlnit un proces de recrutare atât de uman și profesionist în același timp.$q$, $q$I greatly appreciated the fairness and attention to detail. Each candidate was evaluated not only for their skills, but also for their compatibility with the team. I have rarely encountered a recruitment process so humane and professional at the same time.$q$, 2),
  ($q$Beatrice G.$q$, $q$Manager cabinet avocatură$q$, $q$Law Firm Manager$q$, $q$De la primul contact până la semnarea contractului, m-am simțit respectată și ascultată. Diana și echipa ei m-au ghidat cu răbdare, oferindu-mi feedback real și sprijin sincer.$q$, $q$From the first contact to signing the contract, I felt respected and listened to. Diana and her team guided me patiently, giving me real feedback and sincere support.$q$, 3),
  ($q$Raluca V.$q$, $q$Director HR$q$, $q$HR Director$q$, $q$Diana are un mod unic de a conecta oamenii potriviți cu organizațiile potrivite. Nu livrează doar candidați, ci soluții de echipă.$q$, $q$Diana has a unique way of connecting the right people with the right organizations. She doesn't just deliver candidates, she delivers team solutions.$q$, 4)
) as t(name, role_ro, role_en, quote_ro, quote_en, sort_order)
where not exists (select 1 from public.fw_testimonials);
